import { paginate } from '../../lib/pagination.ts';
import type { CreateLabel, Label, ListLabelsQuery, LabelPage } from './schema.ts';

const labels = new Map<string, Label>();
const idempotencyStore = new Map<string, Label>();

const sortKey = (label: Label): string => `${label.createdAt}|${label.id}`;

export function listLabels(query: ListLabelsQuery): LabelPage {
  const items = Array.from(labels.values());
  return paginate(items, query, sortKey);
}

export function getLabel(id: string): Label | undefined {
  return labels.get(id);
}

export function createLabel(input: CreateLabel): Label {
  const id = randomUUID();
  const label: Label = {
    id,
    name: input.name,
    color: input.color,
    createdAt: new Date().toISOString(),
  };
  labels.set(id, label);
  return label;
}

export function getIdempotent(key: string): Label | undefined {
  return idempotencyStore.get(key);
}

export function setIdempotent(key: string, label: Label): void {
  idempotencyStore.set(key, label);
}

